SELECT ,NULL AS texts_json,NULL AS body_valid
FROM training_answer a 
WHERE a.owner_id=#{owner} AND a.id=#{id}

SELECT ,
FROM training_answer a 
WHERE a.owner_id=#{owner} AND a.id=#{id}

SELECT f.owner_id,f.id,f.session_id,f.question_id,f.answer_id
FROM review_feedback f JOIN review_feedback_revision v
  ON v.owner_id=f.owner_id AND v.feedback_id=f.id AND v.revision=#{revision}
WHERE f.owner_id=#{owner} AND f.id=#{id}

SELECT 
FROM review_feedback f JOIN review_feedback_revision v
  ON v.owner_id=f.owner_id AND v.feedback_id=f.id AND v.revision=#{revision}

WHERE f.owner_id=#{owner} AND f.id=#{id}

SELECT 
FROM review_recollection r JOIN review_recollection_version v
  ON v.owner_id=r.owner_id AND v.recollection_id=r.id AND v.id=#{versionId}

WHERE r.owner_id=#{owner} AND r.id=#{id}
